<script setup lang="ts">
import LeakSummary from "../../components/LeakSummary.vue";
import EmergencyBrief from "../../components/EmergencyBrief.vue";
import {computed} from 'vue';import {useRealtimeStore} from '../../store/useRealtimeStore';import {useRiskPrediction} from '../../composables/useRiskPrediction';import {floodLevelLabels} from '../../types/flood';import DigitalTwinScene from '../../components/digital-twin/DigitalTwinScene.vue';import FloodRiskCard from '../Simulation/components/FloodRiskCard.vue';import PredictionCharts from './components/PredictionCharts.vue';import '../Simulation/flood.css';import './risk.css';
const realtime=useRealtimeStore();const {prediction,model,explanation,evaluation,error}=useRiskPrediction(computed(()=>!realtime.state?.leak?.scenarioId),true);
const flood=computed(()=>realtime.state?.flood),active=computed(()=>!!flood.value?.scenarioId),compare=computed(()=>prediction.value?.comparison.find(x=>x.minute===30));
const agreementLabels={high:'高',medium:'中',low:'低'};const trend=computed(()=>{const history=realtime.floodHistory;const now=history.at(-1);if(!now)return null;const earlier=history.find(p=>p.time>=now.time-600);return earlier&&now.time-earlier.time>=590?now.riskScore-earlier.riskScore:null;});
</script><template><LeakSummary v-if="realtime.state?.leak?.scenarioId" detailed/><template v-else><EmergencyBrief/><div class="section-heading"><div><span class="eyebrow">RISK INTELLIGENCE</span><h2>风险研判中心</h2></div><RouterLink class="risk-demo-link" to="/simulation">进入暴雨场景 →</RouterLink></div><p class="risk-scope">物理模型与机器学习预测联合展示 · 软件仿真训练 · 模型一致度不代表统计置信度。</p><p v-if="error" role="alert">{{error}}</p><p v-if="realtime.connectionStatus!=='connected'" class="risk-stale">实时连接已断开，保留上次预测。</p><div class="risk-layout" data-testid="risk-page" :data-scenario="flood?.scenarioId??''"><aside class="risk-left"><FloodRiskCard v-if="active&&flood" :state="flood"/><section v-else class="panel risk-empty"><h3>当前规则风险</h3><strong>—</strong><p>暂无活动事故场景</p><small>启动内涝场景后，查看当前规则风险与未来趋势。</small></section><section class="panel risk-trend-summary"><h3>当前风险趋势</h3><strong>{{trend===null?'—':`${trend>=0?'+':''}${trend.toFixed(1)}`}}<small> / 10 仿真分钟</small></strong><p>{{trend===null?'历史样本积累中':'来自已发生的仿真观测'}}</p><p>左侧贡献为当前规则风险来源，与未来 ML 解释分开展示。</p></section></aside><main class="risk-middle"><DigitalTwinScene :realtime-state="realtime.state" initial-mode="risk"/><section class="panel risk-comparison" data-testid="risk-comparison"><header><h3>物理模型 × 机器学习 <small>+30 min</small></h3><span v-if="compare" :class="compare.agreement" data-testid="risk-agreement">模型一致度 · {{agreementLabels[compare.agreement]}}</span></header><template v-if="prediction?.physicalForecast.length"><div class="comparison-numbers"><div><span>物理预测</span><strong>{{prediction.physicalForecast.at(-1)?.waterLevel.toFixed(1)}}<small> cm</small></strong><p>风险 {{prediction.physicalForecast.at(-1)?.riskScore.toFixed(1)}}</p></div><div><span>机器学习预测</span><strong>{{prediction.mlForecast.at(-1)?.waterLevel.toFixed(1)??'—'}}<small> cm</small></strong><p>风险 {{prediction.mlForecast.at(-1)?.riskScore.toFixed(1)??'—'}}</p></div><div><span>预测差异</span><strong>{{compare?.waterGap.toFixed(2)??'—'}}<small> cm</small></strong><p>风险差 {{compare?.riskGap.toFixed(2)??'—'}}</p></div></div><small>{{prediction.assumption}}</small><p>预测基准：第 {{(prediction.simulationTime/60).toFixed(1)}} 仿真分钟 · 每5秒更新</p></template><p v-else>暂无活动事故场景，启动后对比两种预测。</p></section><section class="panel risk-evaluation" data-testid="risk-evaluation"><h3>已到期预测与实际演化对照</h3><div v-if="evaluation&&evaluation.samples"><strong>{{evaluation.waterMae?.toFixed(2)}} cm <small>水位 MAE</small></strong><strong>{{evaluation.riskMae?.toFixed(2)}} <small>风险 MAE</small></strong><span>{{evaluation.samples}} 个已到期预测</span></div><p v-else>预测样本积累中 · 到达预测时刻后计算真实误差</p><small>{{evaluation?.message}}</small></section></main><aside class="risk-right"><section class="panel risk-future" data-testid="risk-forecast" :data-revision="prediction?.basedOnRevision??0" :data-available="prediction?.modelStatus.available??false"><h3>未来风险与水位 <small>机器学习预测</small></h3><p v-if="prediction&&!prediction.modelStatus.available" data-testid="risk-model-missing">模型未加载，保留物理预测。</p><div v-for="p in prediction?.mlForecast??[]" :key="p.minute" class="risk-horizon" :data-horizon="p.minute"><span>+{{p.minute}} min</span><strong>{{p.waterLevel.toFixed(1)}}<small> cm</small></strong><div>风险 {{p.riskScore.toFixed(1)}} · {{floodLevelLabels[p.riskLevel]}}</div></div><p v-if="!active">暂无活动事故场景</p></section><section class="panel risk-explanation" data-testid="risk-explanation" :data-method="explanation?.method"><h3>未来风险的主要因素</h3><template v-if="explanation?.available"><small>{{explanation.method==='native_tree_shap'?'模型解释 · 可加和贡献':'模型解释 · 近似排序'}}</small><div v-for="f in explanation.topFeatures.slice(0,6)" :key="f.feature" class="risk-feature"><span>{{f.label}}</span><b>{{explanation.method==='native_tree_shap'&&f.contribution>0?'+':''}}{{f.contribution.toFixed(2)}}{{explanation.method==='native_tree_shap'?' 分':''}}</b><i><em :style="{width:`${Math.min(100,f.share)}%`}"></em></i></div><details class="model-explanation-details"><summary>解释方法与边界</summary><p>{{explanation.method==='native_tree_shap'?'XGBoost 原生 TreeSHAP':'特征重要性与偏离度近似'}} · {{explanation.message}}</p></details><small>解释基准：{{((explanation.simulationTime??0)/60).toFixed(1)}} 仿真分钟</small></template><p v-else>{{explanation?.message??'等待预测解释'}}</p></section></aside></div><PredictionCharts :prediction="prediction" :history="realtime.floodHistory"/><section class="panel risk-model" data-testid="risk-model-status"><header><h3>模型详情 <small>XGBoost</small></h3><span>{{model?.version??prediction?.modelStatus.version??'未加载'}} · {{model?.featureVersion??'—'}}</span></header><p>{{(model?.datasetSize??0)>0?`${model!.datasetSize.toLocaleString()} 条仿真样本`:'训练信息不可用'}} · 场景划分 {{model?.scenarioCounts.train??'—'}} / {{model?.scenarioCounts.validation??'—'}} / {{model?.scenarioCounts.test??'—'}} · 训练 / 验证 / 测试</p><details class="risk-model-details"><summary>查看训练信息与独立测试指标（{{Object.keys(model?.metrics??{}).length}} 个目标模型）</summary><p>训练集用于学习，验证集选择参数，独立测试集报告指标；按场景划分，保持事件隔离。</p><div class="risk-metrics-scroll"><table><thead><tr><th>测试目标</th><th>MAE</th><th>RMSE</th><th>R²</th><th>等级一致率</th></tr></thead><tbody><tr v-for="(m,key) in model?.metrics??{}" :key="key"><td>{{key}}</td><td>{{m.mae.toFixed(3)}}</td><td>{{m.rmse.toFixed(3)}}</td><td>{{m.r2.toFixed(4)}}</td><td>{{m.risk_level_accuracy===undefined?'—':`${(m.risk_level_accuracy*100).toFixed(1)}%`}}</td></tr></tbody></table></div></details><small>模型只拟合当前软件仿真分布；这些指标不证明真实园区预测能力。{{model?.storageAvailable===false?'预测存储暂不可用。':''}}</small></section></template></template>
